from datetime import datetime, timezone

NOW = datetime(2026, 10, 21, 7, 27, 50, tzinfo=timezone.utc)

class Clock:
    def __init__(self, t=0.0):
        self.t = t
    def __call__(self):
        return self.t

@test("seconds")
def _():
    check_eq(parse_retry_after("12", NOW), 12)
    check_eq(parse_retry_after(" 0 ", NOW), 0)
    check_eq(parse_retry_after("120", NOW), 120)

@test("HTTP dates")
def _():
    check_eq(parse_retry_after("Wed, 21 Oct 2026 07:28:00 GMT", NOW), 10)
    check_eq(parse_retry_after("Wed, 21 Oct 2026 07:20:00 GMT", NOW), 0)
    later = datetime(2026, 10, 21, 7, 27, 59, 500000, tzinfo=timezone.utc)
    check_eq(parse_retry_after("Wed, 21 Oct 2026 07:28:00 GMT", later), 1)

@test("invalid values")
def _():
    for bad in (None, "", "   ", "-5", "1.5", "soon", "Wed, 21 Oct 2026 07:28:00"):
        check_eq(parse_retry_after(bad, NOW), None)

@test("a full bucket allows a burst")
def _():
    clock = Clock()
    b = TokenBucket(rate=2, capacity=3, clock=clock)
    check_eq([b.try_take() for _ in range(4)], [True, True, True, False])
    check_near(b.wait_time(), 0.5)

@test("refilling over time")
def _():
    clock = Clock()
    b = TokenBucket(rate=2, capacity=3, clock=clock)
    for _ in range(3):
        b.try_take()
    clock.t = 0.25
    check(not b.try_take())
    check_near(b.wait_time(), 0.25)
    clock.t = 0.5
    check_eq(b.wait_time(), 0)
    check(b.try_take())
    check(not b.try_take())

@test("never above capacity")
def _():
    clock = Clock()
    b = TokenBucket(rate=10, capacity=2, clock=clock)
    clock.t = 100
    check_eq([b.try_take() for _ in range(3)], [True, True, False])

@test("waiting does not take")
def _():
    clock = Clock()
    b = TokenBucket(rate=1, capacity=1, clock=clock)
    check_eq(b.wait_time(), 0)
    check_eq(b.wait_time(), 0)
    check(b.try_take())
    check_near(b.wait_time(), 1.0)

